import { existsSync, readFileSync } from 'node:fs';

// Read the known audit file — the second test-assertion channel alongside the UI (DESIGN.md §3,
// docs/SUT_CONTRACT.md §4). The app appends one record per line; /__test__/reset clears it per
// spec. Path comes from AUDIT_FILE (set by bin/start / bin/e2e); falls back to the app's default.
const AUDIT_FILE = process.env.AUDIT_FILE ?? '../.run/audit.log';

/** All audit records currently in the file, one per element (empty if none). */
export function auditLines(): string[] {
  return existsSync(AUDIT_FILE)
    ? readFileSync(AUDIT_FILE, 'utf8').split('\n').filter((l) => l.length > 0)
    : [];
}

// Usage in a spec (audit-category test):
//   expect(auditLines()).toContain('OWNER_CREATED id=1 name=Acme');

import { useQuery } from '@tanstack/react-query';
import { projectsKey, listProjects, type Project } from './api';
import { ProjectRow } from '../../slots/defs/projectRow';
import { ProjectsToolbar } from '../../slots/defs/projectsToolbar';
import { useSearchParam, asFlag, asNumber, asString } from '../../url/useSearchParam';

// The projects list. Reads server data under ['projects'] (never copied into state); the create form
// shares the key, so a successful create refreshes this list with no import between them. Each row
// shows the client's NAME, which the server joins onto the project.
//
// Archived projects are tucked away: they drop off the list unless the `showArchived` URL key is on.
// The toggle control (its own *.slot.tsx) owns that key; this list reads the same key and filters,
// so they stay in step through the shared search param with nothing passed between them.
export function ProjectsList() {
  const [showArchived] = useSearchParam('showArchived', asFlag);
  // The tag filter control (its own *.slot.tsx) owns this key; the list reads the same key and keeps
  // only the projects carrying that tag, so they stay in step through the shared search param with
  // nothing passed between them. Unset clears the key, so the list falls back to every project.
  const [tagFilter] = useSearchParam('projectTag', asNumber);
  // The status filter control (its own *.slot.tsx) owns this key; the list reads the same key and
  // keeps only the projects at that lifecycle status, so they stay in step through the shared
  // search param with nothing passed between them. An empty key means every status.
  const [statusFilter] = useSearchParam('projectStatus', asString);
  const { data: projects } = useQuery({ queryKey: projectsKey, queryFn: listProjects });

  if (!projects) {
    return null;
  }

  const visible = projects.filter(
    (project: Project) =>
      (showArchived || !project.archived) &&
      (tagFilter === undefined || project.tagIds.includes(tagFilter)) &&
      (statusFilter === '' || project.status === statusFilter),
  );

  return (
    <>
      <ProjectsToolbar.Slot />
      {visible.length === 0 ? (
        <p data-testid="projects-empty">No projects yet.</p>
      ) : (
        <ProjectsTable projects={visible} />
      )}
    </>
  );
}

function ProjectsTable({ projects }: { projects: Project[] }) {
  return (
    <table data-testid="projects-table">
      <thead>
        <tr>
          <th>Name</th>
          <th>Client</th>
          <th></th>
        </tr>
      </thead>
      <tbody>
        {projects.map((project: Project) => (
          <tr key={project.id} data-testid={`project-row-${project.id}`}>
            <td data-testid="project-name">{project.name}</td>
            <td data-testid="project-client">{project.clientName}</td>
            <td>
              <ProjectRow.Slot projectId={project.id} />
            </td>
          </tr>
        ))}
      </tbody>
    </table>
  );
}

